#include "knowledge_retrieval_page.hpp"
#include "request_authorization_widget.hpp"
#include "knowledge_search_index.hpp"
#include "knowledge_ai_host.hpp"
#include <QtWidgets>
KnowledgeRetrievalPage::KnowledgeRetrievalPage(QJsonObject h,QString q,Sources s,Preferences p,std::function<void()> e,QWidget*parent,QNetworkAccessManager*fake):QWidget(parent),held(std::move(h)),sources(std::move(s)),preferences(std::move(p)),exit(std::move(e)){
 setObjectName("knowledgeRetrievalPage");runner=new aiKnowledge::Runner(this,fake);auto outer=new QVBoxLayout(this);auto title=new QLabel("本机证据检索 · 逐块选择后预览 · 默认无授权与凭据；仅所选证据片段可主动外发");title->setWordWrap(true);outer->addWidget(title);message=new QLabel("先填写检索词并检索；不会默认勾选证据。只检索已选资料的本机正文。");message->setWordWrap(true);message->setObjectName("retrievalMessage");message->setTextFormat(Qt::PlainText);message->setMaximumHeight(fontMetrics().lineSpacing()*3+12);outer->addWidget(message);
 auto bar=new QHBoxLayout;outer->addLayout(bar);auto add=[&](QLayout*l,QString label,QString name,std::function<void()> fn){auto b=new QPushButton(label);b->setObjectName(name);l->addWidget(b);connect(b,&QPushButton::clicked,this,[this,b,fn]{if(allowed(b))guard(fn);});return b;};
 add(bar,"完整状态 / 检索边界","retrievalStatus",[this]{reader->setPlainText(message->text()+"\n\n完整检索与本机校验包\n"+QString::fromUtf8(QJsonDocument(result).toJson()));stack->setCurrentIndex(1);});add(bar,"返回资料选择","retrievalExit",[this]{cancel();if(exit)exit();});add(bar,"返回检索列表","retrievalBack",[this]{back();});add(bar,"取消并清除检索预览","retrievalCancel",[this]{cancel();});stack=new QStackedWidget;stack->setObjectName("retrievalStack");outer->addWidget(stack,1);
 auto main=new QWidget;auto layout=new QVBoxLayout(main);auto form=new QFormLayout;layout->addLayout(form);question=new QLineEdit(q);question->setObjectName("retrievalQuestion");query=new QLineEdit(q.size()<=500?q:QString());query->setObjectName("retrievalQuery");query->setPlaceholderText("明确检索词，最多500个UTF-16单位");form->addRow("研究问题",question);form->addRow("检索词",query);auto options=new QHBoxLayout;topK=new QSpinBox;topK->setObjectName("retrievalTopK");topK->setRange(1,50);topK->setValue(10);mode=new QComboBox;mode->setObjectName("retrievalMode");QStringList labels{"作者观点","时间变化","规则检查","反证 / 冲突","候选比较"};auto values=knowledgeRetrieval::modes();for(int i=0;i<values.size();++i)mode->addItem(labels[i],values[i]);options->addWidget(new QLabel("返回块数"));options->addWidget(topK);options->addWidget(mode,1);layout->addLayout(options);
 auto scope=new QLabel;scope->setObjectName("retrievalScope");scope->setWordWrap(true);scope->setTextFormat(Qt::PlainText);QStringList names;for(auto v:held["materials"].toArray()){auto d=v.toObject();names.append(knowledgeAiHost::identity(d)+" · "+d["row"].toObject()["title"].toString());}for(auto v:held["materials"].toArray())if(v.toObject().contains("legacyKnowledgeWarning"))names.append(v.toObject()["legacyKnowledgeWarning"].toString());scope->setText("本次明确范围：\n"+names.join('\n')+"\n优先实测本机FTS5 / trigram / BM25，仅为所选资料评分；不支持或无命中明确字面回退。最多10块/每来源3块；不检索 originalText。");layout->addWidget(scope);
 auto tools=new QHBoxLayout;layout->addLayout(tools);add(tools,"核对来源并检索","retrievalSearch",[this]{retrieve();});add(tools,"阅读命中对应完整来源","retrievalRead",[this]{readSource();});add(tools,"组装所选证据 / 预览","retrievalPreview",[this]{preview();});hits=new QListWidget;hits->setObjectName("retrievalHits");hits->setWordWrap(true);hits->setMinimumHeight(240);layout->addWidget(hits,1);auto mainScroll=new QScrollArea;mainScroll->setWidgetResizable(true);mainScroll->setWidget(main);stack->addWidget(mainScroll);
 reader=new QPlainTextEdit;reader->setObjectName("retrievalSourceReader");reader->setReadOnly(true);reader->setLineWrapMode(QPlainTextEdit::WidgetWidth);stack->addWidget(reader);
 auto previewPage=new QWidget;auto pl=new QVBoxLayout(previewPage);authority=new RequestAuthorizationWidget([this]{return allowed();},this);pl->addWidget(authority);authority->expired=[this]{cancel();};add(pl,"发送当前已授权证据请求","retrievalSend",[this]{sendAuthorized();});add(pl,"检查未授权请求（只会阻断）","retrievalBlockedCheck",[this]{blockedCheck();});previewText=new QPlainTextEdit;previewText->setObjectName("retrievalContextReader");previewText->setReadOnly(true);pl->addWidget(previewText,1);stack->addWidget(previewPage);
 connect(qApp,&QGuiApplication::applicationStateChanged,this,[this](Qt::ApplicationState s){if(s!=Qt::ApplicationActive)cancel();});
 connect(query,&QLineEdit::textChanged,this,[this]{if(!loading&&allowed(query))invalidate(true);});connect(topK,&QSpinBox::valueChanged,this,[this]{if(!loading&&allowed(topK))invalidate(true);});connect(question,&QLineEdit::textChanged,this,[this]{if(!loading&&allowed(question))invalidate(false);});connect(mode,&QComboBox::currentIndexChanged,this,[this]{if(!loading&&allowed(mode))invalidate(false);});connect(hits,&QListWidget::itemChanged,this,[this](auto*i){if(!loading&&allowed(hits))guard([this,i]{select(i);});});
}
bool KnowledgeRetrievalPage::allowed(const QWidget*origin)const{return !closed&&isVisible()&&isEnabled()&&!window()->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive&&entryCheck()&&(!origin||(origin->isVisible()&&origin->isEnabled()));}
QString KnowledgeRetrievalPage::researchQuestion()const{return question->text();}
void KnowledgeRetrievalPage::guard(const std::function<void()>&fn){try{fn();}catch(const std::exception&e){message->setText(QString::fromUtf8(e.what()));}}
void KnowledgeRetrievalPage::checkSources(){try{if(!sources)throw std::runtime_error("完整资料接口未接入");knowledgeAiHost::confirm(held,sources());}catch(...){invalidate(true);stack->setCurrentIndex(0);throw;}}
void KnowledgeRetrievalPage::invalidate(bool clearResults){if(authority)authority->clear();runner->cancel();prepared.reset();context={};attempt={};previewText->clear();if(clearResults){result={};selectedIds={};loading=true;hits->clear();loading=false;reader->clear();}}
void KnowledgeRetrievalPage::retrieve(){invalidate(true);checkSources();result=knowledgeSearchIndex::search(held["materials"].toArray(),query->text(),topK->value());loading=true;for(auto v:result["items"].toArray()){auto h=v.toObject();QString lineage=h.contains("legacyProvenance")?"旧证据 "+h["legacyEvidenceId"].toString()+" · 原块ID "+QString::number(h["legacyProvenance"].toObject()["chunk"].toObject()["id"].toInt())+"\n":QString();QString stamp=h["publishedAt"].toString();if(stamp.isEmpty())stamp="未知";auto item=new QListWidgetItem(h["sourceKey"].toString()+" · "+h["title"].toString()+" · "+stamp+QString(" · UTF-16[%1,%2)\n").arg(h["charStart"].toInt()).arg(h["charEnd"].toInt())+lineage+h["content"].toString(),hits);item->setData(Qt::UserRole,h);item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(Qt::Unchecked);}loading=false;
 message->setText((result["engineLabel"].toString()+QString(" · 共%1块，命中%2块，返回%3块，topK外遗漏%4块。未默认选择。实际词：%5；回退未用词：%6。")).arg(result["totalChunks"].toInt()).arg(result["matchedChunks"].toInt()).arg(result["items"].toArray().size()).arg(result["omittedByTopK"].toInt()).arg(QString::fromUtf8(QJsonDocument(result["usedTokens"].toArray()).toJson(QJsonDocument::Compact))).arg(QString::fromUtf8(QJsonDocument(result["unusedFallbackTokens"].toArray()).toJson(QJsonDocument::Compact)))+" 24词上限外遗漏："+QString::fromUtf8(QJsonDocument(result["tokensBeyondLimit"].toArray()).toJson(QJsonDocument::Compact)));}
void KnowledgeRetrievalPage::select(QListWidgetItem*item){checkSources();QJsonArray candidate;QHash<QString,int> counts;for(int i=0;i<hits->count();++i){auto r=hits->item(i);if(r->checkState()==Qt::Checked){auto h=r->data(Qt::UserRole).toJsonObject();candidate.append(h["evidenceId"]);++counts[h["sourceKey"].toString()];}}bool valid=candidate.size()<=10;for(auto n:counts)valid=valid&&n<=3;if(!valid){loading=true;auto id=item->data(Qt::UserRole).toJsonObject()["evidenceId"];bool had=selectedIds.contains(id);item->setCheckState(had?Qt::Checked:Qt::Unchecked);loading=false;throw std::runtime_error("最多10块、每来源3块；原选择保留，未自动裁剪");}selectedIds=candidate;invalidate(false);message->setText(QString("已明确选择%1块。组装预览前会再次核对完整来源版本。").arg(selectedIds.size()));}
void KnowledgeRetrievalPage::readSource(){checkSources();if(!hits->currentItem())throw std::runtime_error("先点选一条命中以阅读完整来源");auto hit=hits->currentItem()->data(Qt::UserRole).toJsonObject();QJsonObject d;for(auto v:held["materials"].toArray())if(knowledgeAiHost::identity(v.toObject())==hit["sourceKey"])d=v.toObject();auto row=d["row"].toObject();QString prefix=hit["sourceKey"].toString()+"\n原发布时间："+hit["publishedAt"].toString()+"\n来源版本："+hit["reference"].toObject()["rowSha256"].toString()+QString("\n命中位置：row.text UTF-16[%1,%2)；保留原换行，非规范化字符串。\n\n完整本机正文\n").arg(hit["charStart"].toInt()).arg(hit["charEnd"].toInt());if(hit.contains("legacyProvenance")){auto old=hit["legacyProvenance"].toObject();auto chunk=old["chunk"].toObject();prefix="旧证据："+chunk["evidence_id"].toString()+" · 原块ID："+QString::number(chunk["id"].toInt())+"\n原块创建："+chunk["created_at"].toString()+"\n旧来源更新："+old["sourceUpdatedAt"].toString()+"\n旧来源正文版本："+old["sourceContentHash"].toString()+"\n"+(old["sourceMetadataEqual"].toBool()?QString():QString("旧来源元数据与当前记录版本不同；正文和原偏移逐字一致，两份原记录均保留。\n"))+prefix;}reader->setPlainText(prefix+row["text"].toString()+"\n\n完整 originalText（未检索）\n"+row["originalText"].toString()+"\n\n完整来源记录\n"+QString::fromUtf8(QJsonDocument(d).toJson()));auto position=[&](int offset){QString shown=prefix+row["text"].toString().left(offset);shown.replace("\r\n","\n");shown.replace('\r','\n');return shown.size();};QTextCursor cursor=reader->textCursor();cursor.setPosition(position(hit["charStart"].toInt()));cursor.setPosition(position(hit["charEnd"].toInt()),QTextCursor::KeepAnchor);reader->setTextCursor(cursor);stack->setCurrentIndex(1);reader->ensureCursorVisible();}
void KnowledgeRetrievalPage::preview(){invalidate(false);checkSources();context=knowledgeRetrieval::context(result,selectedIds,question->text(),mode->currentData().toString());QString text="所选证据的完整外发提示（仅提示中的片段和元数据将外发）\n\n"+context["prompt"].toString();try{if(!preferences)throw std::runtime_error("非敏感配置接口未接入");prepared=aiKnowledge::prepareEvidence(preferences(),context);authority->bind({*prepared});text+="\n\n精确供应商请求body（完整，无截断）\n"+QString::fromUtf8(aiKnowledge::bytes(prepared->preview()["requestBody"].toObject()));}catch(const std::exception&e){text+="\n\n供应商请求未形成："+QString::fromUtf8(e.what())+"；本机上下文仍完整可读。";}text+="\n\n完整本机核对包（来源全文保留本机，以下JSON不是实际外发body）\n"+QString::fromUtf8(QJsonDocument(context).toJson());previewText->setPlainText(text);stack->setCurrentIndex(2);message->setText("已组装明确选入的证据，遗漏边界在预览中；默认无授权与凭据；预览后须主动授权当前请求。");}
void KnowledgeRetrievalPage::blockedCheck(){checkSources();if(!prepared)throw std::runtime_error("尚未形成可核对的供应商请求，请检查非敏感模型配置");runner->start(*prepared,{}, {},[this](QJsonObject a){if(!allowed())return;attempt=a;message->setText("未授权检查："+a["status"].toString()+" · "+a["errorCode"].toString()+" · networkAttempted="+(a["networkAttempted"].toBool()?"true":"false"));});}
void KnowledgeRetrievalPage::cancel(){if(closed)return;invalidate(true);stack->setCurrentIndex(0);message->setText("已取消，检索结果、证据选择和外发预览失效；原宿主完整资料仍保留。");}
void KnowledgeRetrievalPage::close(){if(closed)return;cancel();closed=true;setEnabled(false);}
bool KnowledgeRetrievalPage::back(){if(!allowed()||stack->currentIndex()==0)return false;invalidate(false);stack->setCurrentIndex(0);return true;}
void KnowledgeRetrievalPage::hideEvent(QHideEvent*e){cancel();QWidget::hideEvent(e);}

KnowledgeRetrievalPage::~KnowledgeRetrievalPage(){close();}
void KnowledgeRetrievalPage::sendAuthorized(){checkSources();if(!prepared||!authority->ready()||runner->running())throw std::runtime_error("先预览、核对并主动授权本次证据请求");auto heldRequest=*prepared;auto grant=authority->authorize(heldRequest);runner->start(heldRequest,grant,[this]{return authority->acquire();},[this](QJsonObject a){if(!allowed())return;authority->clear();attempt=a;reader->setPlainText(QString::fromUtf8(QJsonDocument(a).toJson()));stack->setCurrentIndex(1);message->setText("证据请求："+a["status"].toString()+"；结果仍需核验，未保存或启动其他请求。");});}
